import numpy as np
from scipy.fft import rfft, irfft, next_fast_len

class Solver:
    def solve(self, problem, **kwargs):
        x_list = problem["signal_x"]
        y_list = problem["signal_y"]
        mode = problem.get("mode", "full")

        n1 = len(x_list)
        n2 = len(y_list)
        if n1 == 0 or n2 == 0:
            if mode == "full":
                return {"convolution": [0.0] * max(0, n1 + n2 - 1)}
            elif mode == "same":
                return {"convolution": [0.0] * n1}
            elif mode == "valid":
                return {"convolution": [0.0] * max(0, n1 - n2 + 1) if n1 >= n2 else []}

        arr_x = np.fromiter(x_list, dtype=np.float32, count=n1)
        arr_y = np.fromiter(y_list, dtype=np.float32, count=n2)

        shape = n1 + n2 - 1
        fshape = next_fast_len(shape)

        sp1 = rfft(arr_x, fshape)
        sp2 = rfft(arr_y, fshape)
        sp1 *= sp2
        ret = irfft(sp1, fshape, overwrite_x=True)[0:shape]

        if mode == "same":
            newsize = n1
            startind = (shape - newsize) // 2
            ret = ret[startind:startind+newsize]
        elif mode == "valid":
            newsize = max(n1, n2) - min(n1, n2) + 1
            startind = (shape - newsize) // 2
            ret = ret[startind:startind+newsize]

        return {"convolution": ret.tolist()}
